184		private ClassicHttpResponse execute(HttpUriRequest request, URI url, String description) {
185			try {
186				HttpHost host = HttpHost.create(url);
187				request.addHeader("User-Agent", "SpringBootCli/" + getClass().getPackage().getImplementationVersion());
188				return getHttp().executeOpen(host, request, null);
189			}
190			catch (IOException ex) {
191				throw new ReportableException(
192						"Failed to " + description + " from service at '" + url + "' (" + ex.getMessage() + ")");
193			}
194		}
