196		private ReportableException createException(String url, ClassicHttpResponse httpResponse) {
197			StatusLine statusLine = new StatusLine(httpResponse);
198			String message = "Initializr service call failed using '" + url + "' - service returned "
199					+ statusLine.getReasonPhrase();
200			String error = extractMessage(httpResponse.getEntity());
201			if (StringUtils.hasText(error)) {
202				message += ": '" + error + "'";
203			}
204			else {
205				int statusCode = statusLine.getStatusCode();
206				message += " (unexpected " + statusCode + " error)";
207			}
208			return new ReportableException(message);
209		}
